      if (success && !input_data_view.ReadUtterance(&p_utterance))
        success = false;
      if (success && !input_data_view.ReadVoice(&p_voice))
        success = false;
      if (success) {
        p_ash_utterance_client =
            input_data_view.TakeAshUtteranceClient<decltype(p_ash_utterance_client)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TtsClient::Name_, 1, false);
        return false;
      }
