void TtsUtteranceClientProxy::OnTtsEvent(
    TtsEventType in_event_type, uint32_t in_char_index, uint32_t in_length, const std::string& in_error_message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send crosapi::mojom::TtsUtteranceClient::OnTtsEvent", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("event_type"), in_event_type,
                        "<value of type TtsEventType>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("char_index"), in_char_index,
                        "<value of type uint32_t>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("length"), in_length,
                        "<value of type uint32_t>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("error_message"), in_error_message,
                        "<value of type const std::string&>");
   });
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;
  
  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kTtsUtteranceClient_OnTtsEvent_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::crosapi::mojom::internal::TtsUtteranceClient_OnTtsEvent_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::Serialize<::crosapi::mojom::TtsEventType>(
      in_event_type, &params->event_type);
  params->char_index = in_char_index;
  params->length = in_length;
  mojo::internal::MessageFragment<
      typename decltype(params->error_message)::BaseType> error_message_fragment(
          params.message());
  mojo::internal::Serialize<mojo::StringDataView>(
      in_error_message, error_message_fragment);
  params->error_message.Set(
      error_message_fragment.is_null() ? nullptr : error_message_fragment.data());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      params->error_message.is_null(),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
      "null error_message in TtsUtteranceClient.OnTtsEvent request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(TtsUtteranceClient::Name_);
  message.set_method_name("OnTtsEvent");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

// static
bool TtsUtteranceClientStubDispatch::Accept(
    TtsUtteranceClient* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kTtsUtteranceClient_OnTtsEvent_Name: {

      DCHECK(message->is_serialized());
      internal::TtsUtteranceClient_OnTtsEvent_Params_Data* params =
          reinterpret_cast<internal::TtsUtteranceClient_OnTtsEvent_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for TtsUtteranceClient.0
      bool success = true;
      TtsEventType p_event_type{};
      uint32_t p_char_index{};
      uint32_t p_length{};
      std::string p_error_message{};
      TtsUtteranceClient_OnTtsEvent_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadEventType(&p_event_type))
        success = false;
      if (success)
        p_char_index = input_data_view.char_index();
      if (success)
        p_length = input_data_view.length();
      if (success && !input_data_view.ReadErrorMessage(&p_error_message))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TtsUtteranceClient::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnTtsEvent(        
        std::move(p_event_type), 
        std::move(p_char_index), 
        std::move(p_length), 
        std::move(p_error_message));
      return true;
    }
  }
  return false;
}

