// static
bool StructTraits<::crosapi::mojom::TtsVoice::DataView, ::crosapi::mojom::TtsVoicePtr>::Read(
    ::crosapi::mojom::TtsVoice::DataView input,
    ::crosapi::mojom::TtsVoicePtr* output) {
  bool success = true;
  ::crosapi::mojom::TtsVoicePtr result(::crosapi::mojom::TtsVoice::New());
  
      if (success && !input.ReadVoiceName(&result->voice_name))
        success = false;
      if (success && !input.ReadLang(&result->lang))
        success = false;
      if (success)
        result->remote = input.remote();
      if (success && !input.ReadEngineId(&result->engine_id))
        success = false;
      if (success && !input.ReadEvents(&result->events))
        success = false;
      if (success)
        result->native = input.native();
      if (success && !input.ReadNativeVoiceIdentifier(&result->native_voice_identifier))
        success = false;
  *output = std::move(result);
  return success;
}


